        YDOT(321)=YDOT(321)+YDOT(nSurface)*surfaceCoverage*Y(238)
        YDOT(322)=YDOT(322)+YDOT(nSurface)*surfaceCoverage*Y(239)
        YDOT(323)=YDOT(323)+YDOT(nSurface)*surfaceCoverage*Y(240)
        YDOT(324)=YDOT(324)+YDOT(nSurface)*surfaceCoverage*Y(241)
        YDOT(325)=YDOT(325)+YDOT(nSurface)*surfaceCoverage*Y(242)
        YDOT(326)=YDOT(326)+YDOT(nSurface)*surfaceCoverage*Y(243)
        YDOT(327)=YDOT(327)+YDOT(nSurface)*surfaceCoverage*Y(244)
        YDOT(328)=YDOT(328)+YDOT(nSurface)*surfaceCoverage*Y(245)
        YDOT(329)=YDOT(329)+YDOT(nSurface)*surfaceCoverage*Y(246)
        YDOT(330)=YDOT(330)+YDOT(nSurface)*surfaceCoverage*Y(247)
        YDOT(331)=YDOT(331)+YDOT(nSurface)*surfaceCoverage*Y(248)
        YDOT(332)=YDOT(332)+YDOT(nSurface)*surfaceCoverage*Y(249)
    end if
    ! Update total rate of change of bulk and surface for bulk growth
            PROD = sum(YDOT(bulkList))
        YDOT(334) = PROD
            PROD = sum(YDOT(surfaceList))
        YDOT(335) = PROD
    end subroutine GETYDOT
end module ODES